 * @param {number[]} nums
 * @return {number}
 */
var sortPermutation = function(nums) {
    const n = nums.length;
    const seen = Array.from({ length: n }, () => false);
    let res = 65_535;

    for (let i = 0; i < n; i++) {
        if (nums[i] === i) continue;

        let lookup = nums[i];

        while (!seen[lookup]) {
            seen[lookup] = true;
            res &= lookup;
            lookup = nums[lookup];
        }
    }

    return res;
};

